create table hotels (id bigint generated by default as identity primary key, name varchar(160) not null, address varchar(300) not null, version bigint not null default 0);
create table rooms (id bigint generated by default as identity primary key, hotel_id bigint not null references hotels(id), number varchar(30) not null, available boolean not null default true, times_booked bigint not null default 0 check(times_booked >= 0), version bigint not null default 0, unique(hotel_id, number));
create table room_reservations (id uuid primary key, booking_id bigint not null, room_id bigint not null references rooms(id), start_date date not null, end_date date not null, state varchar(16) not null check(state in ('ACTIVE','RELEASED','REJECTED')), check(end_date > start_date));
create index ix_reservation_dates on room_reservations(room_id,state,start_date,end_date);
create index ix_room_recommend on rooms(hotel_id,available,times_booked,id);
